<?php
require __DIR__ . '/includes/bootstrap.php';
$rows=query("SELECT c.code AS class_code,s.code,s.name,COUNT(a.session_id) AS total,COALESCE(SUM(a.status='present'),0) AS present,COALESCE(SUM(a.status='absent'),0) AS absent,COALESCE(SUM(a.status='late'),0) AS late,COALESCE(SUM(a.status='unmarked'),0) AS unmarked FROM students s JOIN classes c ON c.id=s.class_id LEFT JOIN attendance a ON a.student_id=s.id GROUP BY s.id,c.code,s.code,s.name ORDER BY c.code,s.code")->fetchAll();
$totals=['present'=>0,'absent'=>0,'late'=>0,'unmarked'=>0]; foreach ($rows as $r) foreach ($totals as $k=>$v) $totals[$k]+=(int)$r[$k];
page_start('Thống kê chuyên cần','statistics.php');
?>
<section class="metrics" aria-label="Thống kê theo trạng thái"><?php $tones=['present'=>'','absent'=>'tone-red','late'=>'tone-amber','unmarked'=>'tone-slate']; $icons=['present'=>'check','absent'=>'users','late'=>'clock','unmarked'=>'calendar']; foreach ($totals as $k=>$v) ui_metric(status_label($k),$v,$icons[$k],$tones[$k]); ?></section><section class="panel"><div class="panel-heading"><div><h2>Chuyên cần theo sinh viên</h2><p>Tổng hợp trên các buổi có trong danh sách điểm danh.</p></div><span class="count-pill"><?= count($rows) ?> sinh viên</span></div><p class="notice">Tỷ lệ tham dự = (có mặt + đi muộn) / số lượt đã điểm danh × 100%. Mẫu số = Có mặt + Vắng mặt + Đi muộn; các lượt chưa điểm danh không nằm trong mẫu số. Khi chưa có lượt đã điểm danh, hiển thị —. Bao gồm sinh viên đã ngừng theo dõi.</p><div class="table-scroll"><table class="statistics-table"><thead><tr><th>Sinh viên</th><th>Lớp</th><th>Tổng buổi</th><th>Có mặt</th><th>Vắng</th><th>Muộn</th><th>Chưa ghi</th><th>Tham dự</th></tr></thead><tbody><?php if (!$rows) echo '<tr><td colspan="8" class="empty">Chưa có dữ liệu thống kê.</td></tr>'; foreach ($rows as $r): $marked=(int)$r['total']-(int)$r['unmarked']; ?><tr><td><span class="student-identity"><?= ui_avatar($r['name']) ?><strong><?= e($r['name']) ?></strong></span><br><small><?= e($r['code']) ?></small></td><td><?= e($r['class_code']) ?></td><td><?= e($r['total']) ?></td><td><?= e($r['present']) ?></td><td><?= e($r['absent']) ?></td><td><?= e($r['late']) ?></td><td><?= e($r['unmarked']) ?></td><td><div class="rate-cell"><span class="rate-value"><?= $marked ? round(((int)$r['present']+(int)$r['late'])/$marked*100,1).'%' : '—' ?></span><?php if ($marked): ?><meter min="0" max="100" value="<?= round(((int)$r['present']+(int)$r['late'])/$marked*100,1) ?>" aria-label="Tỷ lệ tham dự của <?= e($r['name']) ?>"><?= round(((int)$r['present']+(int)$r['late'])/$marked*100,1) ?>%</meter><?php endif; ?></div></td></tr><?php endforeach; ?></tbody></table></div><p class="table-hint">Cuộn ngang để xem số lượt và tỷ lệ tham dự.</p></section><?php page_end(); ?>
